    # Adjust based on my HP
    if my_status['hp'] <= 5:
        # Low HP, need water, bid aggressively
        return min(my_status['budget'], DAILY_SALARY * 0.8)
    else:
        # Healthy HP, bid moderately
        return min(my_status['budget'], DAILY_SALARY * 0.6)

